/**
 * Scrolls the JScrollPane to a specific row in the JTable.
 * @param row The row to scroll to.
 * @param table The JTable the row belongs to.
 * @param pane The JScrollPane to scroll.
 */
public static void scrolltoRow(int row, JTable table, JScrollPane pane) {
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Invalid row index: " + row);
    }
    Rectangle tableRect = table.getCellRect(row, 0, true);
    Rectangle paneRect = pane.getViewportBorderBounds();
    int scrollY = tableRect.y - paneRect.y;
    if (scrollY < 0) {
        scrollY = 0;
    } else if (scrollY > paneRect.height - tableRect.height) {
        scrollY = paneRect.height - tableRect.height;
    }
    pane.getViewport().setViewPosition(new Point(0, scrollY));
}

